-- Administrative reads use a separate NOLOGIN role with SELECT only on analytics.
-- This argument-free guard stays with the migrator, which already has auth schema access.
-- It only checks the caller JWT; it returns no identity or business data.
CREATE FUNCTION public_bot.insight_require_admin() RETURNS void LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$
BEGIN
 IF auth.uid() IS NULL OR public.is_meta_reviewer() OR public.is_atendimentos_viewer() OR NOT public.has_role(auth.uid(),'admin'::public.app_role) THEN RAISE EXCEPTION 'Acesso restrito ao administrador.' USING ERRCODE='42501'; END IF;
END $$;
CREATE FUNCTION public_bot.insight_item(c public_bot.insight_conversations) RETURNS jsonb LANGUAGE sql STABLE SET search_path=pg_catalog AS $$
 SELECT jsonb_build_object('id',c.id,'brand',c.brand,'startedAt',c.started_at,'lastActivityAt',c.last_activity_at,'messages',c.messages,'whatsapp',c.whatsapp,'initialFilters',c.initial_filters,'latestFilters',c.latest_filters,'resultCount',c.result_count)
$$;
CREATE FUNCTION public.public_bot_insights(days integer DEFAULT 7) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public_bot AS $$
DECLARE since date; until date:=(now() AT TIME ZONE 'America/Sao_Paulo')::date; output jsonb;
BEGIN
 PERFORM public_bot.insight_require_admin();
 IF days IS NULL OR days NOT IN (1,7,30) THEN RAISE EXCEPTION 'Período inválido.' USING ERRCODE='22023'; END IF;
 since:=until-days+1;
 WITH series AS (
  SELECT b.brand,dt::date AS day FROM (VALUES('cordial'),('morar')) b(brand) CROSS JOIN generate_series(since::timestamp,until::timestamp,interval '1 day') dt
 ), daily_values AS (
  SELECT s.brand,s.day,coalesce(d.opens,0) AS opens,coalesce(d.sessions,0) AS sessions,coalesce(d.conversations,0) AS conversations,coalesce(d.messages,0) AS messages,coalesce(d.whatsapp,0) AS whatsapp FROM series s LEFT JOIN public_bot.insight_daily d ON d.brand=s.brand AND d.local_day=s.day
 ), brands AS (
  SELECT brand,jsonb_build_object('brand',brand,'opens',sum(opens),'sessions',sum(sessions),'conversations',sum(conversations),'messages',sum(messages),'whatsapp',sum(whatsapp),'daily',jsonb_agg(jsonb_build_object('date',day,'opens',opens,'sessions',sessions,'conversations',conversations,'messages',messages,'whatsapp',whatsapp) ORDER BY day)) AS value FROM daily_values GROUP BY brand
 ) SELECT jsonb_agg(value ORDER BY brand) INTO output FROM brands;
 RETURN jsonb_build_object('trackingSince',(SELECT tracking_since FROM public_bot.insight_settings WHERE singleton),'period',jsonb_build_object('days',days,'from',since,'to',until,'timezone','America/Sao_Paulo'),'brands',output);
END $$;
CREATE FUNCTION public.public_bot_conversations(b text,days integer DEFAULT 7,page integer DEFAULT 1,page_size integer DEFAULT 20) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public_bot AS $$
DECLARE since timestamptz; n bigint; items jsonb;
BEGIN
 PERFORM public_bot.insight_require_admin();
 IF coalesce(b,'') NOT IN ('cordial','morar') OR days IS NULL OR days NOT IN (1,7,30) OR page IS NULL OR page NOT BETWEEN 1 AND 10000 OR page_size IS NULL OR page_size NOT BETWEEN 1 AND 25 THEN RAISE EXCEPTION 'Consulta inválida.' USING ERRCODE='22023'; END IF;
 since:=(((now() AT TIME ZONE 'America/Sao_Paulo')::date-days+1)::timestamp AT TIME ZONE 'America/Sao_Paulo');
 SELECT count(*) INTO n FROM public_bot.insight_conversations c WHERE c.brand=b AND c.last_activity_at>=since AND c.last_activity_at>now()-interval '30 days';
 SELECT coalesce(jsonb_agg(public_bot.insight_item(c) ORDER BY c.last_activity_at DESC,c.id),'[]') INTO items FROM (SELECT * FROM public_bot.insight_conversations c WHERE c.brand=b AND c.last_activity_at>=since AND c.last_activity_at>now()-interval '30 days' ORDER BY c.last_activity_at DESC,c.id LIMIT page_size OFFSET (page-1)*page_size) c;
 RETURN jsonb_build_object('items',items,'total',n,'page',page,'pageSize',page_size);
END $$;
CREATE FUNCTION public.public_bot_conversation(b text,id uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public_bot AS $$
#variable_conflict use_variable
DECLARE c public_bot.insight_conversations; evolution jsonb; total bigint;
BEGIN
 PERFORM public_bot.insight_require_admin();
 IF coalesce(b,'') NOT IN ('cordial','morar') OR id IS NULL THEN RAISE EXCEPTION 'Consulta inválida.' USING ERRCODE='22023'; END IF;
 SELECT * INTO c FROM public_bot.insight_conversations x WHERE x.brand=b AND x.id=id AND x.last_activity_at>now()-interval '30 days';
 IF c.id IS NULL THEN RETURN NULL; END IF;
 SELECT count(*) INTO total FROM public_bot.insight_evolution e WHERE e.conversation_id=c.id;
 SELECT coalesce(jsonb_agg(jsonb_build_object('at',e.at,'kind',e.kind,'requestId',CASE WHEN e.kind='turn' THEN e.event_id ELSE NULL END,'state',e.state,'question',e.question,'answer',e.answer,'revision',e.revision,'filters',e.filters,'resultCount',e.result_count,'outcome',e.outcome,'publicIds',e.public_ids,'source',e.source) ORDER BY e.at,e.event_id),'[]') INTO evolution FROM (SELECT * FROM public_bot.insight_evolution x WHERE x.conversation_id=c.id ORDER BY x.at DESC,x.event_id DESC LIMIT 500) e;
 RETURN public_bot.insight_item(c)||jsonb_build_object('evolution',evolution,'evolutionTotal',total,'evolutionTruncated',total>500);
END $$;

